var th = p.angle * Math.PI / 180;
var A = p.mag;
var Ax = A * Math.cos(th), Ay = A * Math.sin(th);
var pad = 40;
var span = 26;
var s = Math.min((W - 2 * pad) / (2 * span), (H - 2 * pad) / (2 * span));
var ox = W / 2, oy = H / 2;
var X = function (x) { return ox + x * s; };
var Y = function (y) { return oy - y * s; };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// grid
ctx.strokeStyle = C.faint;
for (var g = -span; g <= span; g += 5) {
  ctx.beginPath(); ctx.moveTo(X(g), Y(-span)); ctx.lineTo(X(g), Y(span)); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(X(-span), Y(g)); ctx.lineTo(X(span), Y(g)); ctx.stroke();
}

// axes
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(X(-span), Y(0)); ctx.lineTo(X(span), Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(0), Y(-span)); ctx.lineTo(X(0), Y(span)); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("x", X(span) - 12, Y(0) + 16);
ctx.fillText("y", X(0) + 8, Y(span) + 14);

// component legs
ctx.strokeStyle = C.figure;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(Ax), Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(Ax), Y(0)); ctx.lineTo(X(Ax), Y(Ay)); ctx.stroke();
ctx.setLineDash([]);

// right-angle tick at the corner
var d = 7 * (Ax >= 0 ? -1 : 1), e = 7 * (Ay >= 0 ? -1 : 1);
ctx.beginPath();
ctx.moveTo(X(Ax) + d, Y(0));
ctx.lineTo(X(Ax) + d, Y(0) + e);
ctx.lineTo(X(Ax), Y(0) + e);
ctx.stroke();

// the vector itself
var ax = X(Ax), ay = Y(Ay);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(ax, ay); ctx.stroke();
var hl = 10, ang = Math.atan2(ay - Y(0), ax - X(0));
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.moveTo(ax, ay);
ctx.lineTo(ax - hl * Math.cos(ang - 0.4), ay - hl * Math.sin(ang - 0.4));
ctx.lineTo(ax - hl * Math.cos(ang + 0.4), ay - hl * Math.sin(ang + 0.4));
ctx.closePath(); ctx.fill();

// angle arc
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.2;
ctx.beginPath();
ctx.arc(X(0), Y(0), 26, 0, -th, th > 0);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("A", (X(0) + ax) / 2 - 14, (Y(0) + ay) / 2 - 6);
ctx.fillText("Ax = " + Ax.toFixed(2), X(Ax / 2) - 22, Y(0) + (Ay >= 0 ? 18 : -8));
ctx.fillText("Ay = " + Ay.toFixed(2), X(Ax) + (Ax >= 0 ? 8 : -60), Y(Ay / 2));
ctx.fillStyle = C.figure;
ctx.fillText(p.angle.toFixed(0) + " deg", X(0) + 30, Y(0) - (th > 0 ? 10 : -20));

out.note = "A = " + A.toFixed(1) + " at " + p.angle.toFixed(0) + " deg   ->   Ax = A cos = " + Ax.toFixed(2) + ",  Ay = A sin = " + Ay.toFixed(2) + "   (check: sqrt(Ax^2+Ay^2) = " + Math.sqrt(Ax * Ax + Ay * Ay).toFixed(2) + ")";

var th = p.angle * Math.PI / 180;
var A = p.magA, B = p.magB;
var pad = 34;
var span = 12;
var s = Math.min((W - 2 * pad) / (2 * span), (H - 2 * pad) / (1.6 * span));
var ox = W * 0.28, oy = H * 0.72;
var X = function (x) { return ox + x * s; };
var Y = function (y) { return oy - y * s; };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

function arrow(x1, y1, x2, y2, col, wid) {
  ctx.strokeStyle = col; ctx.lineWidth = wid;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1), hl = 9;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - hl * Math.cos(a - 0.4), y2 - hl * Math.sin(a - 0.4));
  ctx.lineTo(x2 - hl * Math.cos(a + 0.4), y2 - hl * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

// B lies along +x, A is tilted up by th
var bx = B, by = 0;
var axv = A * Math.cos(th), ayv = A * Math.sin(th);
var proj = A * Math.cos(th);

// baseline through B, extended
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(-2), Y(0)); ctx.lineTo(X(span), Y(0)); ctx.stroke();

// projection bar sitting on B's line
ctx.strokeStyle = C.figure; ctx.lineWidth = 6;
ctx.beginPath(); ctx.moveTo(X(0), Y(0) + 0); ctx.lineTo(X(proj), Y(0)); ctx.stroke();

// dropped perpendicular
ctx.strokeStyle = C.figure; ctx.lineWidth = 1; ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(X(axv), Y(ayv)); ctx.lineTo(X(proj), Y(0)); ctx.stroke();
ctx.setLineDash([]);

arrow(X(0), Y(0), X(bx), Y(by), C.rule, 2.5);
arrow(X(0), Y(0), X(axv), Y(ayv), C.accent, 2.5);

// angle arc
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.2;
ctx.beginPath(); ctx.arc(X(0), Y(0), 24, 0, -th, true); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("B", X(bx) + 6, Y(0) + 16);
ctx.fillText("A", X(axv) + 6, Y(ayv) - 4);
ctx.fillText("A cos(theta) = " + proj.toFixed(2), X(proj / 2) - 34, Y(0) + 26);
ctx.fillStyle = C.figure;
ctx.fillText(p.angle.toFixed(0) + " deg", X(0) + 28, Y(0) - 8);

var dp = A * B * Math.cos(th);
ctx.fillStyle = C.ink;
ctx.fillText("shadow of A on B, times the length of B", W * 0.06, 20);

out.note = "A.B = |A||B|cos(theta) = " + A.toFixed(1) + " x " + B.toFixed(1) + " x " + Math.cos(th).toFixed(3) + " = " + dp.toFixed(2) + "   |   projection of A onto B = " + proj.toFixed(2) + (Math.abs(dp) < 0.05 ? "   (perpendicular)" : "");

var th = p.angle * Math.PI / 180;
var A = p.magA, B = p.magB;
var pad = 30;
var span = 13;
var s = Math.min((W - 2 * pad) / (1.9 * span), (H - 2 * pad) / (1.5 * span));
var ox = W * 0.24, oy = H * 0.80;
var X = function (x) { return ox + x * s; };
var Y = function (y) { return oy - y * s; };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

function arrow(x1, y1, x2, y2, col, wid) {
  ctx.strokeStyle = col; ctx.lineWidth = wid;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1), hl = 9;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - hl * Math.cos(a - 0.4), y2 - hl * Math.sin(a - 0.4));
  ctx.lineTo(x2 - hl * Math.cos(a + 0.4), y2 - hl * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

var ax = A, ay = 0;
var bx = B * Math.cos(th), by = B * Math.sin(th);

// parallelogram
ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.moveTo(X(0), Y(0));
ctx.lineTo(X(ax), Y(ay));
ctx.lineTo(X(ax + bx), Y(ay + by));
ctx.lineTo(X(bx), Y(by));
ctx.closePath(); ctx.fill();
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath();
ctx.moveTo(X(ax), Y(ay)); ctx.lineTo(X(ax + bx), Y(ay + by)); ctx.lineTo(X(bx), Y(by));
ctx.stroke();
ctx.setLineDash([]);

// height = B sin(th)
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.4;
ctx.setLineDash([5, 4]);
ctx.beginPath(); ctx.moveTo(X(bx), Y(by)); ctx.lineTo(X(bx), Y(0)); ctx.stroke();
ctx.setLineDash([]);

arrow(X(0), Y(0), X(ax), Y(ay), C.rule, 2.5);
arrow(X(0), Y(0), X(bx), Y(by), C.accent, 2.5);

ctx.strokeStyle = C.figure; ctx.lineWidth = 1.2;
ctx.beginPath(); ctx.arc(X(0), Y(0), 26, 0, -th, true); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("A", X(ax) + 6, Y(0) + 16);
ctx.fillText("B", X(bx) + 6, Y(by) - 6);
ctx.fillText("h = B sin(theta) = " + (B * Math.sin(th)).toFixed(2), X(bx) + 8, Y(by / 2));
ctx.fillStyle = C.figure;
ctx.fillText(p.angle.toFixed(0) + " deg", X(0) + 30, Y(0) - 8);

// the out-of-page vector, drawn as a circled dot or cross to the right
var cx = W * 0.86, cy = H * 0.30, r = 13;
var area = A * B * Math.sin(th);
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.accent;
if (area >= 0) {
  ctx.beginPath(); ctx.arc(cx, cy, 3.5, 0, Math.PI * 2); ctx.fill();
} else {
  ctx.beginPath();
  ctx.moveTo(cx - 7, cy - 7); ctx.lineTo(cx + 7, cy + 7);
  ctx.moveTo(cx + 7, cy - 7); ctx.lineTo(cx - 7, cy + 7);
  ctx.stroke();
}
ctx.fillStyle = C.ink;
ctx.fillText("A x B", cx - 18, cy + r + 16);
ctx.fillText(area >= 0 ? "out of page" : "into page", cx - 30, cy + r + 32);

out.note = "|A x B| = |A||B|sin(theta) = " + A.toFixed(1) + " x " + B.toFixed(1) + " x " + Math.abs(Math.sin(th)).toFixed(3) + " = " + Math.abs(area).toFixed(2) + " = shaded area" + (Math.abs(area) < 0.05 ? "   (parallel: zero)" : "");

var wRiver = 150;           // metres across
var vCur = p.current;
var vBoat = p.boat;
var head = p.heading * Math.PI / 180;   // measured from straight-across, positive = upstream

// boat velocity relative to ground: x downstream, y across
var vx = vCur - vBoat * Math.sin(head);
var vy = vBoat * Math.cos(head);

var tCross = vy > 0.001 ? wRiver / vy : 0;
var drift = vx * tCross;

var pad = 34;
var xSpanRaw = Math.max(Math.abs(drift) * 1.25, 60);
var sx = (W - 2 * pad) / (2 * xSpanRaw);
var sy = (H - 2 * pad) / wRiver;
var ox = W / 2, oyB = H - pad;
var X = function (x) { return ox + x * sx; };
var Y = function (y) { return oyB - y * sy; };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// banks
ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(0, Y(0)); ctx.lineTo(W, Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(0, Y(wRiver)); ctx.lineTo(W, Y(wRiver)); ctx.stroke();

// current arrows
ctx.strokeStyle = C.faint; ctx.lineWidth = 1.5;
for (var k = 1; k <= 5; k++) {
  var yy = Y(wRiver * k / 6);
  ctx.beginPath(); ctx.moveTo(W * 0.08, yy); ctx.lineTo(W * 0.08 + 26, yy); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 0.08 + 26, yy); ctx.lineTo(W * 0.08 + 20, yy - 4);
  ctx.moveTo(W * 0.08 + 26, yy); ctx.lineTo(W * 0.08 + 20, yy + 4);
  ctx.stroke();
}

// straight-across reference
ctx.strokeStyle = C.faint; ctx.lineWidth = 1; ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(wRiver)); ctx.stroke();
ctx.setLineDash([]);

if (tCross > 0) {
  // whole path
  ctx.strokeStyle = C.rule; ctx.lineWidth = 1; ctx.setLineDash([4, 5]);
  ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(drift), Y(wRiver)); ctx.stroke();
  ctx.setLineDash([]);

  var now = (t % (tCross + 1.2));
  var cur = Math.min(now, tCross);
  ctx.strokeStyle = C.accent; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(vx * cur), Y(vy * cur)); ctx.stroke();

  var px = X(vx * cur), py = Y(vy * cur);
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(px, py, 5, 0, Math.PI * 2); ctx.fill();

  // heading arrow (velocity relative to water)
  ctx.strokeStyle = C.figure; ctx.lineWidth = 1.6;
  var hx = px - vBoat * Math.sin(head) * 9, hy = py - vBoat * Math.cos(head) * 9;
  ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(hx, hy); ctx.stroke();
  ctx.fillStyle = C.figure;
  ctx.fillText("heading", hx + 6, hy);

  ctx.fillStyle = C.ink;
  ctx.fillText("landing", X(drift) + 6, Y(wRiver) + 16);
} else {
  ctx.fillStyle = C.ink;
  ctx.fillText("heading too far upstream: she never reaches the far bank", W * 0.12, H / 2);
}

ctx.fillStyle = C.ink;
ctx.fillText("far bank", 8, Y(wRiver) - 8);
ctx.fillText("start", X(0) + 8, Y(0) - 8);
ctx.fillStyle = C.figure;
ctx.fillText("current " + vCur.toFixed(1) + " m/s", W * 0.08, Y(wRiver * 0.5) - 12);

out.note = tCross > 0
  ? "crossing takes " + tCross.toFixed(1) + " s,  downstream drift " + drift.toFixed(1) + " m   (drift = (" + vCur.toFixed(1) + " - " + (vBoat * Math.sin(head)).toFixed(2) + ") x " + tCross.toFixed(1) + ")"
  : "across-stream speed is zero: she never lands";
